APPLE_AGX_BOOL AppleAgxRenderTemplateMaterialize(
    void *Arena, APPLE_AGX_U32 ArenaCapacity,
    APPLE_AGX_RENDER_TEMPLATE_ROOTS *Roots) {
  unsigned char *arena = (unsigned char *)Arena;
  APPLE_AGX_U32 index;
  APPLE_AGX_U32 runIndex;

  if (arena == (void *)0 || Roots == (void *)0 ||
      ArenaCapacity < APPLE_AGX_RENDER_TEMPLATE_BYTES)
    return APPLE_AGX_FALSE;
  for (index = 0u; index < APPLE_AGX_RENDER_TEMPLATE_BYTES; ++index)
    arena[index] = 0u;
  for (runIndex = 0u;
       runIndex < (APPLE_AGX_U32)(sizeof(AppleAgxRenderTemplateRuns) /
                                  sizeof(AppleAgxRenderTemplateRuns[0]));
       ++runIndex) {
    const APPLE_AGX_RENDER_TEMPLATE_RUN *run =
        &AppleAgxRenderTemplateRuns[runIndex];
    for (index = 0u; index < run->Bytes; ++index)
      arena[run->ImageOffset + index] =
          AppleAgxRenderTemplateData[run->DataOffset + index];
  }
  Roots->Ta[0] = 0x1503880000ULL;
  Roots->Ta[1] = 0x1503898000ULL;
  Roots->D3[0] = 0x1503870000ULL;
  Roots->D3[1] = 0x1503890000ULL;
  return APPLE_AGX_TRUE;
}

APPLE_AGX_BOOL AppleAgxRenderTemplateBuildRelocationObjects(
    void *Arena, APPLE_AGX_U32 ArenaCapacity,
    APPLE_AGX_U64 ArenaPhysicalAddress,
    APPLE_AGX_EXP208_RELOCATION_OBJECT *Objects,
    APPLE_AGX_U32 ObjectCapacity) {
  unsigned char *arena = (unsigned char *)Arena;
  APPLE_AGX_U32 index;
  const APPLE_AGX_U64 maximumAddress = ~(APPLE_AGX_U64)0;

  if (arena == (void *)0 || Objects == (void *)0 ||
      ArenaCapacity < APPLE_AGX_RENDER_TEMPLATE_BYTES ||
      ObjectCapacity < APPLE_AGX_RENDER_TEMPLATE_RUNTIME_OBJECT_COUNT ||
      ArenaPhysicalAddress >
          maximumAddress - APPLE_AGX_RENDER_TEMPLATE_BYTES)
    return APPLE_AGX_FALSE;
  for (index = 0u; index < APPLE_AGX_RENDER_TEMPLATE_OBJECT_COUNT;
       ++index) {
    const APPLE_AGX_RENDER_TEMPLATE_OBJECT_LAYOUT *layout =
        &AppleAgxRenderTemplateLayouts[index];
    Objects[index].GpuVa = layout->PackedGpuVa;
    Objects[index].PhysicalAddress =
        ArenaPhysicalAddress + layout->ArenaOffset;
    Objects[index].Size = layout->Size;
    Objects[index].Data = arena + layout->ArenaOffset;
  }
  Objects[APPLE_AGX_RENDER_TEMPLATE_ARENA_OBJECT_INDEX].GpuVa =
      APPLE_AGX_RENDER_TEMPLATE_GPU_BASE;
  Objects[APPLE_AGX_RENDER_TEMPLATE_ARENA_OBJECT_INDEX].PhysicalAddress =
      ArenaPhysicalAddress;
  Objects[APPLE_AGX_RENDER_TEMPLATE_ARENA_OBJECT_INDEX].Size =
      APPLE_AGX_RENDER_TEMPLATE_BYTES;
  Objects[APPLE_AGX_RENDER_TEMPLATE_ARENA_OBJECT_INDEX].Data = arena;
  return APPLE_AGX_TRUE;
}
